package com.bank.portal.web; import com.bank.portal.domain.*; import com.bank.portal.service.BankingService; import com.bank.portal.web.ApiDtos.*; import jakarta.validation.Valid; import java.time.LocalDate; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/transactions") @RequiredArgsConstructor public class TransactionController {private final BankingService service; @PostMapping("/purchase") @PreAuthorize("hasRole('CUSTOMER')") public TransactionView purchase(@Valid @RequestBody PurchaseRequest r,Authentication a){return service.purchase(r,a.getName());}@GetMapping public List<TransactionView> search(@RequestParam(required=false) Long cardId,@RequestParam(required=false) Long customerId,@RequestParam(required=false) Long merchantId,@RequestParam(required=false) TransactionType type,@RequestParam(required=false) TransactionStatus status,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to,Authentication a){boolean staff=a.getAuthorities().stream().anyMatch(x->x.getAuthority().equals("ROLE_STAFF"));return service.search(cardId,customerId,merchantId,type,status,from,to,a.getName(),staff);}@GetMapping("/recent") @PreAuthorize("hasRole('CUSTOMER')") public List<TransactionView> recent(Authentication a){return service.recent(a.getName());}}
